file22.push(M("cng", { subject: "chemical-eng", chapter: "che-processes", topic: "t-289", difficulty: "medium", question: "The main raw material for cement production is:", optionA: "Bauxite", optionB: "Limestone", optionC: "Sandstone", optionD: "Gypsum", correctAnswer: "B", detailedExplanation: "Cement clinker is made by heating limestone (calcium carbonate) with clay; gypsum is added in small amounts to control setting time. Pakistan has major cement plants in Punjab and KPK.", tags: ["cement industry"] }));
file22.push(M("cng", { subject: "chemical-eng", chapter: "che-processes", topic: "t-289", difficulty: "medium", question: "In petroleum refining, crude oil fractions are separated by:", optionA: "Centrifugation", optionB: "Fractional distillation", optionC: "Electrolysis", optionD: "Evaporation", correctAnswer: "B", detailedExplanation: "Fractional distillation in a distillation column separates crude oil into fractions - LPG, petrol, kerosene, diesel and lubricants - according to their boiling ranges.", tags: ["petroleum refining"] }));
/* industrial-eng */
file22.push(M("ind", { subject: "industrial-eng", chapter: "ind-production", topic: "t-290", difficulty: "easy", question: "TQM stands for:", optionA: "Total Quality Management", optionB: "Total Quantity Measure", optionC: "Technical Quality Model", optionD: "Total Quota Management", correctAnswer: "A", detailedExplanation: "Total Quality Management is a company-wide approach involving all employees in continuous quality improvement to satisfy customers, associated with Deming and Juran.", tags: ["TQM", "quality"] }));
file22.push(M("ind", { subject: "industrial-eng", chapter: "ind-production", topic: "t-290", difficulty: "medium", question: "Six Sigma methodology aims to reduce defects to approximately:", optionA: "1% of output", optionB: "3.4 defects per million opportunities", optionC: "5 defects per thousand", optionD: "Zero material waste", correctAnswer: "B", detailedExplanation: "Six Sigma, popularised by Motorola and General Electric, targets 3.4 defects per million opportunities, using the DMAIC cycle (Define, Measure, Analyse, Improve, Control).", tags: ["six sigma", "quality"] }));
file22.push(M("ind", { subject: "industrial-eng", chapter: "ind-production", topic: "t-291", difficulty: "easy", question: "ISO 9000 series of standards deals with:", optionA: "Environmental management", optionB: "Quality management systems", optionC: "Occupational safety", optionD: "Financial reporting", correctAnswer: "B", detailedExplanation: "The ISO 9000 family specifies requirements for quality management systems, helping organisations consistently meet customer and regulatory requirements.", tags: ["ISO 9000", "standards"] }));
file22.push(M("ind", { subject: "industrial-eng", chapter: "ind-ergonomics", topic: "t-292", difficulty: "easy", question: "Ergonomics is the study of:", optionA: "Earthquake engineering", optionB: "Designing work systems to fit human capabilities", optionC: "Electronic circuits", optionD: "Energy conservation", correctAnswer: "B", detailedExplanation: "Ergonomics (human factors) designs workplaces, tools and tasks to match human physical and cognitive abilities, reducing fatigue, injuries and errors while boosting productivity.", tags: ["ergonomics", "work study"] }));
file22.push(M("ind", { subject: "industrial-eng", chapter: "ind-ergonomics", topic: "t-293", difficulty: "easy", question: "The purpose of time study in work measurement is to:", optionA: "Increase machine speed", optionB: "Determine the standard time for a task", optionC: "Count the number of employees", optionD: "Measure product weight", correctAnswer: "B", detailedExplanation: "Time study, pioneered by F.W. Taylor, measures how long a qualified worker takes to perform a task under standard conditions to establish standard times for planning and incentives.", tags: ["time study", "work study"] }));
/* environmental-eng */
file22.push(M("enve", { subject: "environmental-eng", chapter: "enve-water", topic: "t-294", difficulty: "easy", question: "The first step in conventional drinking water treatment is usually:", optionA: "Chlorination", optionB: "Coagulation and flocculation", optionC: "Filtration", optionD: "Reverse osmosis", correctAnswer: "B", detailedExplanation: "Coagulation and flocculation add chemicals that clump suspended particles, which then settle in sedimentation tanks before sand filtration and final disinfection.", tags: ["water treatment"] }));
file22.push(M("enve", { subject: "environmental-eng", chapter: "enve-water", topic: "t-294", difficulty: "easy", question: "Chlorination of drinking water is done primarily to:", optionA: "Improve taste", optionB: "Kill pathogenic microorganisms", optionC: "Remove hardness", optionD: "Lower water temperature", correctAnswer: "B", detailedExplanation: "Chlorine is a powerful disinfectant that destroys bacteria and viruses in water supplies, protecting against waterborne diseases such as cholera and typhoid.", tags: ["chlorination", "disinfection"] }));
file22.push(M("enve", { subject: "environmental-eng", chapter: "enve-water", topic: "t-295", difficulty: "medium", question: "The activated sludge process is a:", optionA: "Physical screening method", optionB: "Biological wastewater treatment method", optionC: "Chemical precipitation method", optionD: "Thermal oxidation method", correctAnswer: "B", detailedExplanation: "Activated sludge aerates wastewater with microorganisms that decompose organic matter; it is the most common secondary (biological) treatment for municipal sewage.", tags: ["wastewater", "activated sludge"] }));
file22.push(M("enve", { subject: "environmental-eng", chapter: "enve-air", topic: "t-296", difficulty: "medium", question: "BOD (Biochemical Oxygen Demand) measures:", optionA: "Turbidity of water", optionB: "Oxygen required by microorganisms to decompose organic matter in water", optionC: "Dissolved oxygen already present", optionD: "Temperature of the effluent", correctAnswer: "B", detailedExplanation: "BOD quantifies the oxygen microorganisms consume while decomposing organic waste in water; high BOD indicates heavy organic pollution in rivers and industrial effluent.", tags: ["BOD", "water quality"] }));
file22.push(M("enve", { subject: "environmental-eng", chapter: "enve-air", topic: "t-296", difficulty: "medium", question: "An electrostatic precipitator is used to control air pollution by removing:", optionA: "Odour", optionB: "Particulate matter", optionC: "Carbon dioxide", optionD: "Noise", correctAnswer: "B", detailedExplanation: "Electrostatic precipitators charge dust and fly ash particles and collect them on oppositely charged plates, removing up to 99% of particulates from industrial flue gases.", tags: ["electrostatic precipitator", "air pollution"] }));
file22.push(M("enve", { subject: "environmental-eng", chapter: "enve-air", topic: "t-297", difficulty: "easy", question: "Which of the following is a sanitary method of solid waste disposal?", optionA: "Open dumping", optionB: "Sanitary landfilling", optionC: "Burning in the open", optionD: "Dumping in rivers", correctAnswer: "B", detailedExplanation: "Sanitary landfilling compacts waste in lined pits covered daily with soil, preventing leachate and odour problems, unlike open dumping which pollutes air, soil and water.", tags: ["solid waste", "landfill"] }));
/* mechatronics */
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-intro", topic: "t-298", difficulty: "easy", question: "A sensor is a device that:", optionA: "Converts a physical quantity into an electrical signal", optionB: "Converts electrical signals into motion", optionC: "Stores electrical energy", optionD: "Amplifies sound waves", correctAnswer: "A", detailedExplanation: "Sensors (transducers) such as thermocouples, strain gauges and encoders measure temperature, force and position and convert them into electrical signals for control systems.", tags: ["sensors", "mechatronics"] }));
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-intro", topic: "t-298", difficulty: "easy", question: "An actuator converts:", optionA: "Mechanical motion into electricity", optionB: "Electrical signals into mechanical motion", optionC: "Heat into light", optionD: "Pressure into temperature", correctAnswer: "B", detailedExplanation: "Actuators such as DC motors, servos, solenoids and pneumatic cylinders convert electrical or hydraulic commands into controlled mechanical movement.", tags: ["actuators", "mechatronics"] }));
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-intro", topic: "t-299", difficulty: "easy", question: "In a closed-loop control system, the output is:", optionA: "Ignored by the controller", optionB: "Measured and fed back to correct the input", optionC: "Always equal to the input", optionD: "Converted to digital only", correctAnswer: "B", detailedExplanation: "Closed-loop (feedback) systems sense the output with a transducer and compare it with the set point, adjusting the input to minimise error - as in room thermostats and servo drives.", tags: ["control systems", "feedback"] }));
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-intro", topic: "t-299", difficulty: "medium", question: "PID controller stands for:", optionA: "Proportional-Integral-Derivative", optionB: "Power-Input-Digital", optionC: "Process-Index-Device", optionD: "Phase-Integrated-Data", correctAnswer: "A", detailedExplanation: "A PID controller combines proportional (current error), integral (past error) and derivative (predicted error) actions to give accurate, stable industrial process control.", tags: ["PID", "control"] }));
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-robotics", topic: "t-300", difficulty: "easy", question: "The number of independent movements a robot arm can make is called its:", optionA: "Payload", optionB: "Degrees of freedom", optionC: "Repeatability", optionD: "Workspace volume", correctAnswer: "B", detailedExplanation: "Degrees of freedom count each independent joint motion (linear or rotary); an industrial six-axis robot has six degrees of freedom, giving it human-arm-like flexibility.", tags: ["robotics", "degrees of freedom"] }));
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-robotics", topic: "t-300", difficulty: "easy", question: "A servo motor is preferred in robotics because it provides:", optionA: "Very high speed only", optionB: "Precise position and speed control with feedback", optionC: "No rotation", optionD: "Steam power", correctAnswer: "B", detailedExplanation: "Servo motors integrate a motor with an encoder and control electronics to achieve accurate closed-loop position, speed and torque control, ideal for robot joints.", tags: ["servo motor", "robotics"] }));
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-robotics", topic: "t-301", difficulty: "medium", question: "PLC stands for:", optionA: "Programmable Logic Controller", optionB: "Primary Load Circuit", optionC: "Parallel Line Converter", optionD: "Power Level Computer", correctAnswer: "A", detailedExplanation: "A PLC is an industrial digital computer that executes ladder-logic programs to control machines and processes in factories - the backbone of industrial automation.", tags: ["PLC", "automation"] }));
file22.push(M("mecx", { subject: "mechatronics", chapter: "mecx-robotics", topic: "t-301", difficulty: "medium", question: "CNC machines are controlled by:", optionA: "Hand wheels only", optionB: "Pre-programmed numerical commands", optionC: "Hydraulic levers", optionD: "Manual templates", correctAnswer: "B", detailedExplanation: "Computer Numerical Control machines follow coded instructions (G-code) that position cutting tools automatically, enabling precise, repeatable machining of complex parts.", tags: ["CNC", "automation"] }));

/* ================= 23: Medical Sciences ================= */
const file23 = [];
/* anatomy */
