file23.push(M("med", { subject: "anatomy", chapter: "ana-basics", topic: "t-302", difficulty: "easy", question: "The longest bone in the human body is the:", optionA: "Humerus", optionB: "Tibia", optionC: "Femur", optionD: "Fibula", correctAnswer: "C", detailedExplanation: "The femur (thigh bone) is the longest and strongest bone, bearing the body's weight; the stapes in the ear is the smallest bone.", tags: ["femur", "bones"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-basics", topic: "t-302", difficulty: "medium", question: "Which structure connects bones to bones at a joint?", optionA: "Tendon", optionB: "Ligament", optionC: "Cartilage", optionD: "Fascia", correctAnswer: "B", detailedExplanation: "Ligaments are tough bands of fibrous tissue joining bone to bone, stabilising joints; tendons attach muscle to bone and cartilage cushions joint surfaces.", tags: ["ligaments", "joints"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-basics", topic: "t-303", difficulty: "easy", question: "The number of cranial bones in the adult skull is:", optionA: "8", optionB: "12", optionC: "14", optionD: "22", correctAnswer: "A", detailedExplanation: "The skull has 8 cranial bones (frontal, parietal x2, temporal x2, occipital, sphenoid, ethmoid) that enclose the brain, plus 14 facial bones.", tags: ["skull", "cranial bones"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-basics", topic: "t-303", difficulty: "easy", question: "Which muscle is the prime flexor of the elbow joint?", optionA: "Deltoid", optionB: "Triceps brachii", optionC: "Biceps brachii", optionD: "Pectoralis major", correctAnswer: "C", detailedExplanation: "The biceps brachii flexes the elbow and supinates the forearm, while the triceps brachii at the back of the arm is the extensor.", tags: ["muscles", "biceps"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-organs", topic: "t-304", difficulty: "easy", question: "The heart is located in which region of the chest?", optionA: "Left side of the mediastinum", optionB: "Right pleural cavity", optionC: "Posterior mediastinum", optionD: "Abdominal cavity", correctAnswer: "A", detailedExplanation: "The heart sits in the middle mediastinum of the thorax, slightly tilted to the left, between the lungs and behind the sternum.", tags: ["heart", "thorax"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-organs", topic: "t-304", difficulty: "easy", question: "The liver is situated mainly in the:", optionA: "Left upper quadrant", optionB: "Right upper quadrant of the abdomen", optionC: "Pelvic cavity", optionD: "Right lower quadrant", correctAnswer: "B", detailedExplanation: "The liver, the largest internal organ, occupies most of the right upper quadrant, protected by the rib cage; it performs over 500 metabolic functions.", tags: ["liver", "abdomen"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-organs", topic: "t-305", difficulty: "easy", question: "The number of pairs of cranial nerves in humans is:", optionA: "10", optionB: "12", optionC: "16", optionD: "31", correctAnswer: "B", detailedExplanation: "There are 12 pairs of cranial nerves (I-XII) arising from the brain, while 31 pairs of spinal nerves arise from the spinal cord.", tags: ["cranial nerves", "nervous system"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-organs", topic: "t-305", difficulty: "medium", question: "The blood-brain barrier is mainly formed by:", optionA: "Red blood cells", optionB: "Tight junctions of brain capillary endothelial cells", optionC: "Meninges", optionD: "Cerebrospinal fluid only", correctAnswer: "B", detailedExplanation: "Tight junctions between capillary endothelial cells and surrounding astrocytes create the blood-brain barrier, selectively protecting neurons from toxins and pathogens.", tags: ["blood-brain barrier"] }));
file23.push(M("med", { subject: "anatomy", chapter: "ana-organs", topic: "t-305", difficulty: "medium", question: "The functional unit of the kidney is the:", optionA: "Alveolus", optionB: "Nephron", optionC: "Neuron", optionD: "Acinus", correctAnswer: "B", detailedExplanation: "Each kidney contains about one million nephrons - the filtering units made of glomerulus and tubules that form urine and regulate fluid balance.", tags: ["kidney", "nephron"] }));
/* physiology */
file23.push(M("med", { subject: "physiology", chapter: "phy-systems", topic: "t-306", difficulty: "easy", question: "The normal resting heart rate for an adult is approximately:", optionA: "40-50 beats per minute", optionB: "60-100 beats per minute", optionC: "120-150 beats per minute", optionD: "200 beats per minute", correctAnswer: "B", detailedExplanation: "Normal adult resting heart rate is 60-100 bpm, regulated by the sinoatrial (SA) node; athletes may have slower rates due to greater stroke volume.", tags: ["heart rate", "cardiovascular"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-systems", topic: "t-306", difficulty: "easy", question: "Cardiac output is calculated as:", optionA: "Heart rate x stroke volume", optionB: "Heart rate x blood pressure", optionC: "Stroke volume x blood viscosity", optionD: "Blood pressure x resistance", correctAnswer: "A", detailedExplanation: "Cardiac output (about 5 L/min at rest) equals heart rate multiplied by stroke volume - the volume of blood each ventricle pumps per beat.", tags: ["cardiac output", "cardiovascular"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-systems", topic: "t-306", difficulty: "easy", question: "Gas exchange between air and blood in the lungs takes place in the:", optionA: "Bronchi", optionB: "Alveoli", optionC: "Trachea", optionD: "Larynx", correctAnswer: "B", detailedExplanation: "Alveoli are millions of thin-walled air sacs where oxygen diffuses into blood and carbon dioxide out, across a membrane only one cell thick.", tags: ["alveoli", "respiratory"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-systems", topic: "t-307", difficulty: "easy", question: "Which hormone increases blood calcium levels?", optionA: "Calcitonin", optionB: "Parathyroid hormone", optionC: "Insulin", optionD: "Thyroxine", correctAnswer: "B", detailedExplanation: "Parathyroid hormone (PTH) raises blood calcium by stimulating bone resorption, kidney calcium reabsorption and vitamin D activation; calcitonin does the opposite.", tags: ["parathyroid hormone", "endocrine"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-systems", topic: "t-307", difficulty: "medium", question: "Insulin is secreted by which cells of the pancreas?", optionA: "Alpha cells", optionB: "Beta cells of the islets of Langerhans", optionC: "Acinar cells", optionD: "Delta cells", correctAnswer: "B", detailedExplanation: "Beta cells in the islets of Langerhans secrete insulin to lower blood glucose; alpha cells secrete glucagon to raise it.", tags: ["insulin", "pancreas"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-systems", topic: "t-307", difficulty: "medium", question: "The primary function of the kidneys is to:", optionA: "Produce bile", optionB: "Filter blood and maintain fluid and electrolyte balance", optionC: "Digest proteins", optionD: "Store glucose", correctAnswer: "B", detailedExplanation: "Nephrons filter the blood, reabsorb useful solutes and excrete waste in urine, regulating water, electrolytes, pH and blood pressure through renin.", tags: ["kidney function", "renal"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-nerve", topic: "t-308", difficulty: "easy", question: "The neurotransmitter released at the neuromuscular junction is:", optionA: "Dopamine", optionB: "Acetylcholine", optionC: "Serotonin", optionD: "GABA", correctAnswer: "B", detailedExplanation: "Acetylcholine released from motor nerve endings binds receptors on the muscle fibre, triggering contraction; it is destroyed by acetylcholinesterase after release.", tags: ["acetylcholine", "neuromuscular"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-nerve", topic: "t-308", difficulty: "medium", question: "An action potential is best described as:", optionA: "A slow chemical drift", optionB: "A rapid, all-or-none electrical signal along a neuron membrane", optionC: "Continuous passive diffusion", optionD: "A mechanical wave", correctAnswer: "B", detailedExplanation: "An action potential is a brief reversal of membrane potential caused by voltage-gated sodium and potassium channels, propagated along the axon as an all-or-none impulse.", tags: ["action potential", "nerve"] }));
file23.push(M("med", { subject: "physiology", chapter: "phy-nerve", topic: "t-309", difficulty: "medium", question: "Muscle contraction is initiated when calcium binds to:", optionA: "Myosin heads", optionB: "Troponin on the actin filament", optionC: "ATPase", optionD: "Sarcolemma", correctAnswer: "B", detailedExplanation: "Calcium released from the sarcoplasmic reticulum binds troponin, shifting tropomyosin to expose actin binding sites so myosin cross-bridges can pull the filaments.", tags: ["muscle contraction"] }));
/* pathology */
file23.push(M("med", { subject: "pathology", chapter: "pat-general", topic: "t-310", difficulty: "easy", question: "The four cardinal signs of acute inflammation are:", optionA: "Fever, cough, fatigue, rash", optionB: "Redness, swelling, heat, pain", optionC: "Nausea, vomiting, diarrhoea, cramps", optionD: "Itching, scaling, blistering, oozing", correctAnswer: "B", detailedExplanation: "Acute inflammation presents rubor (redness), tumor (swelling), calor (heat) and dolor (pain) from vasodilation, increased permeability and inflammatory mediators; loss of function is the fifth sign.", tags: ["inflammation"] }));
file23.push(M("med", { subject: "pathology", chapter: "pat-general", topic: "t-310", difficulty: "medium", question: "Necrosis refers to:", optionA: "Programmed cell death", optionB: "Cell death in a living organism due to injury or disease", optionC: "Cell division", optionD: "Inflammatory exudate", correctAnswer: "B", detailedExplanation: "Necrosis is unprogrammed cell death caused by ischaemia, toxins or infection, and is often accompanied by inflammation; apoptosis is the controlled form of cell death.", tags: ["necrosis", "cell injury"] }));
file23.push(M("med", { subject: "pathology", chapter: "pat-general", topic: "t-311", difficulty: "easy", question: "A benign tumour is characterised by:", optionA: "Metastasis to distant organs", optionB: "Localised growth without invasion or spread", optionC: "Rapid uncontrolled spread", optionD: "Invasion of blood vessels", correctAnswer: "B", detailedExplanation: "Benign tumours grow slowly, are encapsulated, well-differentiated and do not invade or metastasise; malignant tumours invade surrounding tissue and spread.", tags: ["neoplasia", "benign tumour"] }));
file23.push(M("med", { subject: "pathology", chapter: "pat-systemic", topic: "t-312", difficulty: "easy", question: "Atherosclerosis primarily involves:", optionA: "Nerve degeneration", optionB: "Fatty plaque buildup in artery walls", optionC: "Bone demineralisation", optionD: "Muscle atrophy", correctAnswer: "B", detailedExplanation: "Atherosclerosis is the progressive deposition of cholesterol-rich plaques in arterial intima, narrowing vessels and causing heart attacks, strokes and peripheral artery disease.", tags: ["atherosclerosis", "cardiovascular"] }));
file23.push(M("med", { subject: "pathology", chapter: "pat-systemic", topic: "t-313", difficulty: "easy", question: "The spread of malignant cells to distant organs is called:", optionA: "Hypertrophy", optionB: "Metastasis", optionC: "Hyperplasia", optionD: "Metaplasia", correctAnswer: "B", detailedExplanation: "Metastasis is the hallmark of malignancy - cancer cells travel through blood or lymphatics to colonise distant sites such as liver, lungs or bones.", tags: ["metastasis", "cancer"] }));
/* microbiology */
file23.push(M("med", { subject: "microbiology", chapter: "mic-bacteria", topic: "t-314", difficulty: "easy", question: "Bacteria are classified as:", optionA: "Eukaryotes", optionB: "Prokaryotes", optionC: "Viruses", optionD: "Fungi", correctAnswer: "B", detailedExplanation: "Bacteria are single-celled prokaryotes lacking a true nucleus and membrane-bound organelles, with circular DNA in the cytoplasm; they reproduce by binary fission.", tags: ["bacteria", "prokaryotes"] }));
file23.push(M("med", { subject: "microbiology", chapter: "mic-bacteria", topic: "t-314", difficulty: "medium", question: "Gram staining differentiates bacteria based on:", optionA: "Cell wall peptidoglycan content", optionB: "Presence of nucleus", optionC: "Flagella length", optionD: "Capsule colour", correctAnswer: "A", detailedExplanation: "Gram-positive bacteria have a thick peptidoglycan layer that retains crystal violet and appear purple; gram-negative bacteria have a thin layer plus outer membrane and appear pink.", tags: ["gram staining"] }));
file23.push(M("med", { subject: "microbiology", chapter: "mic-bacteria", topic: "t-315", difficulty: "easy", question: "Mycobacterium tuberculosis is the causative agent of:", optionA: "Cholera", optionB: "Tuberculosis", optionC: "Malaria", optionD: "Influenza", correctAnswer: "B", detailedExplanation: "M. tuberculosis causes pulmonary and extrapulmonary TB; it is an acid-fast bacillus spread by airborne droplets and treated with a multi-drug regimen.", tags: ["tuberculosis"] }));
file23.push(M("med", { subject: "microbiology", chapter: "mic-viruses", topic: "t-316", difficulty: "easy", question: "HIV is classified as a:", optionA: "DNA virus", optionB: "Retrovirus", optionC: "Bacteriophage", optionD: "Prion", correctAnswer: "B", detailedExplanation: "HIV is a retrovirus carrying RNA that is reverse-transcribed into DNA by reverse transcriptase and integrated into host chromosomes, leading to AIDS if untreated.", tags: ["HIV", "retrovirus"] }));
file23.push(M("med", { subject: "microbiology", chapter: "mic-viruses", topic: "t-317", difficulty: "easy", question: "Malaria is caused by which microorganism?", optionA: "Virus", optionB: "Protozoan Plasmodium", optionC: "Bacterium", optionD: "Helminth", correctAnswer: "B", detailedExplanation: "Plasmodium species (falciparum, vivax, etc.) are protozoan parasites transmitted by Anopheles mosquitoes; P. falciparum causes the most severe disease.", tags: ["malaria", "plasmodium"] }));
file23.push(M("med", { subject: "microbiology", chapter: "mic-viruses", topic: "t-317", difficulty: "medium", question: "Penicillin kills bacteria by:", optionA: "Inhibiting protein synthesis", optionB: "Inhibiting cell wall synthesis", optionC: "Blocking DNA replication", optionD: "Disrupting the cell membrane", correctAnswer: "B", detailedExplanation: "Beta-lactams like penicillin block the transpeptidase enzymes that cross-link peptidoglycan, weakening the bacterial cell wall so cells lyse - most effective on growing bacteria.", tags: ["penicillin", "antibiotics"] }));
/* biochemistry */
file23.push(M("med", { subject: "biochemistry", chapter: "bic-molecules", topic: "t-318", difficulty: "easy", question: "In DNA, adenine always pairs with:", optionA: "Guanine", optionB: "Cytosine", optionC: "Thymine", optionD: "Uracil", correctAnswer: "C", detailedExplanation: "Complementary base pairing in DNA follows Chargaff's rules: adenine pairs with thymine (A-T) via two hydrogen bonds and guanine with cytosine (G-C) via three.", tags: ["DNA", "base pairing"] }));
file23.push(M("med", { subject: "biochemistry", chapter: "bic-molecules", topic: "t-318", difficulty: "easy", question: "Enzymes are biological catalysts that work by:", optionA: "Raising activation energy", optionB: "Lowering the activation energy of reactions", optionC: "Being consumed in reactions", optionD: "Changing the equilibrium constant", correctAnswer: "B", detailedExplanation: "Enzymes, mostly proteins, lower activation energy by stabilising the transition state at their active sites, enormously speeding up biochemical reactions without being consumed.", tags: ["enzymes"] }));
file23.push(M("med", { subject: "biochemistry", chapter: "bic-molecules", topic: "t-318", difficulty: "easy", question: "The energy currency of the cell is:", optionA: "DNA", optionB: "ATP", optionC: "Glucose", optionD: "NADH", correctAnswer: "B", detailedExplanation: "ATP (adenosine triphosphate) stores energy in its high-energy phosphate bonds and powers biosynthesis, transport and mechanical work in the cell.", tags: ["ATP", "energy"] }));
file23.push(M("med", { subject: "biochemistry", chapter: "bic-metabolism", topic: "t-320", difficulty: "easy", question: "Glycolysis takes place in the:", optionA: "Mitochondria", optionB: "Cytoplasm", optionC: "Nucleus", optionD: "Ribosomes", correctAnswer: "B", detailedExplanation: "Glycolysis, the breakdown of glucose to pyruvate with net 2 ATP, occurs in the cytoplasm; the Krebs cycle and oxidative phosphorylation occur in mitochondria.", tags: ["glycolysis", "metabolism"] }));
file23.push(M("med", { subject: "biochemistry", chapter: "bic-metabolism", topic: "t-320", difficulty: "medium", question: "Vitamin C deficiency causes:", optionA: "Rickets", optionB: "Scurvy", optionC: "Beriberi", optionD: "Night blindness", correctAnswer: "B", detailedExplanation: "Scurvy results from vitamin C deficiency, causing bleeding gums and poor wound healing because vitamin C is required for collagen synthesis; rickets is vitamin D deficiency.", tags: ["vitamin C", "scurvy"] }));
