file23.push(M("med", { subject: "histology", chapter: "his-tissues", topic: "t-322", difficulty: "easy", question: "Which tissue type lines the inner surfaces of body cavities and organs?", optionA: "Connective tissue", optionB: "Epithelial tissue", optionC: "Nervous tissue", optionD: "Adipose tissue", correctAnswer: "B", detailedExplanation: "Epithelial tissue covers body surfaces and lines cavities, providing protection, absorption, secretion and sensation; it rests on a basement membrane.", tags: ["epithelial tissue", "histology"] }));
file23.push(M("med", { subject: "histology", chapter: "his-tissues", topic: "t-322", difficulty: "easy", question: "Cartilage-producing cells are called:", optionA: "Osteocytes", optionB: "Chondrocytes", optionC: "Fibroblasts", optionD: "Adipocytes", correctAnswer: "B", detailedExplanation: "Chondrocytes maintain cartilage, residing in spaces called lacunae; osteocytes are bone cells and fibroblasts produce connective tissue fibres.", tags: ["cartilage", "chondrocytes"] }));
file23.push(M("med", { subject: "histology", chapter: "his-tissues", topic: "t-323", difficulty: "medium", question: "Skeletal muscle fibres appear striated because of:", optionA: "Glycogen granules", optionB: "Repeating sarcomere arrangement of actin and myosin", optionC: "Fat droplets", optionD: "Nerve endings", correctAnswer: "B", detailedExplanation: "The regular, repeating sarcomeres of actin and myosin filaments give skeletal and cardiac muscle their striated appearance under the microscope.", tags: ["muscle histology", "striations"] }));
file23.push(M("med", { subject: "histology", chapter: "his-organs", topic: "t-324", difficulty: "medium", question: "The alveoli of the lungs are lined by which epithelium?", optionA: "Stratified squamous", optionB: "Simple squamous", optionC: "Transitional", optionD: "Pseudostratified ciliated", correctAnswer: "B", detailedExplanation: "Alveoli are lined by simple squamous epithelium (type I pneumocytes) one cell thick, maximising gas diffusion between air and capillaries.", tags: ["alveoli", "epithelium"] }));
