file23.push(M("med", { subject: "dental-materials", chapter: "den-restorative", topic: "t-326", difficulty: "easy", question: "Dental amalgam is an alloy of mercury with:", optionA: "Gold and platinum", optionB: "Silver, tin and copper", optionC: "Zinc and lead", optionD: "Nickel and chromium", correctAnswer: "B", detailedExplanation: "Amalgam mixes mercury with a silver-tin-copper alloy powder; the mercury binds the particles into a hard, durable filling commonly used for posterior restorations.", tags: ["amalgam", "dental materials"] }));
file23.push(M("med", { subject: "dental-materials", chapter: "den-restorative", topic: "t-326", difficulty: "medium", question: "Composite resin fillings are hardened (cured) using:", optionA: "Heat only", optionB: "Visible blue light", optionC: "Ultrasonic vibration", optionD: "Chemical acid", correctAnswer: "B", detailedExplanation: "Light-cured composites contain camphorquinone photoinitiators that polymerise when exposed to blue light (around 470 nm), allowing the dentist to control setting time.", tags: ["composite", "light curing"] }));
file23.push(M("med", { subject: "dental-materials", chapter: "den-restorative", topic: "t-327", difficulty: "easy", question: "Zinc oxide eugenol cement is commonly used as a:", optionA: "Root filling material only", optionB: "Temporary filling and base", optionC: "Orthodontic bracket", optionD: "Whitening agent", correctAnswer: "B", detailedExplanation: "ZOE cement, made by mixing zinc oxide powder with eugenol liquid, is used for temporary restorations, bases and sedative dressings due to its soothing action on pulp.", tags: ["zinc oxide eugenol", "cements"] }));
file23.push(M("med", { subject: "dental-materials", chapter: "den-properties", topic: "t-328", difficulty: "easy", question: "Alginate is widely used in dentistry as an:", optionA: "Permanent crown material", optionB: "Impression material", optionC: "Cement liner", optionD: "Anesthetic gel", correctAnswer: "B", detailedExplanation: "Alginate, derived from seaweed, is an elastic impression material used to take study models of the mouth; it is mixed with water and sets by gelation.", tags: ["alginate", "impression"] }));
file23.push(M("med", { subject: "dental-materials", chapter: "den-properties", topic: "t-329", difficulty: "medium", question: "The ability of a material to withstand biting forces without breaking is its:", optionA: "Viscosity", optionB: "Strength", optionC: "Solubility", optionD: "Wettability", correctAnswer: "B", detailedExplanation: "Strength - including compressive, tensile and flexural strength - measures a material's resistance to fracture under the high masticatory forces in the mouth.", tags: ["material properties", "strength"] }));

