file24.push(M("med", { subject: "medicine", chapter: "med-internal", topic: "t-330", difficulty: "medium", question: "Type 1 diabetes mellitus is caused by:", optionA: "Insulin resistance only", optionB: "Autoimmune destruction of pancreatic beta cells", optionC: "Excess glucagon", optionD: "Dietary sugar alone", correctAnswer: "B", detailedExplanation: "Type 1 diabetes results from autoimmune destruction of beta cells leading to absolute insulin deficiency, requiring lifelong insulin therapy; type 2 involves insulin resistance.", tags: ["diabetes", "type 1"] }));
