file24.push(M("med", { subject: "medicine", chapter: "med-infectious", topic: "t-333", difficulty: "medium", question: "The first-line treatment for uncomplicated malaria due to P. falciparum is:", optionA: "Aspirin", optionB: "Artemisinin-based combination therapy (ACT)", optionC: "Metformin", optionD: "Paracetamol only", correctAnswer: "B", detailedExplanation: "WHO recommends artemisinin-based combination therapies (ACTs) for uncomplicated falciparum malaria; chloroquine is reserved for sensitive vivax infections.", tags: ["malaria treatment"] }));
