file24.push(M("med", { subject: "surgery", chapter: "sur-general", topic: "t-334", difficulty: "easy", question: "A hernia is defined as:", optionA: "Inflammation of the colon", optionB: "Protrusion of an organ through a defect in its containing wall", optionC: "Obstruction of the bile duct", optionD: "Tearing of a muscle", correctAnswer: "B", detailedExplanation: "A hernia is the protrusion of tissue or organ (commonly bowel) through a weakened abdominal wall, e.g. inguinal or umbilical hernia, which may become strangulated.", tags: ["hernia"] }));
file24.push(M("med", { subject: "surgery", chapter: "sur-general", topic: "t-335", difficulty: "medium", question: "The gold standard method for sterilising surgical instruments is:", optionA: "Boiling in water", optionB: "Autoclaving with steam under pressure", optionC: "Washing with soap", optionD: "Exposure to sunlight", correctAnswer: "B", detailedExplanation: "Autoclaving at 121C with pressurised steam for about 15-20 minutes kills all microorganisms including spores, making it the standard for instrument sterilisation.", tags: ["sterilisation", "autoclave"] }));
file24.push(M("med", { subject: "surgery", chapter: "sur-trauma", topic: "t-336", difficulty: "easy", question: "The 'rule of nines' is used to estimate:", optionA: "Depth of a burn", optionB: "Total body surface area burned", optionC: "Blood loss", optionD: "Pain severity", correctAnswer: "B", detailedExplanation: "The rule of nines assigns multiples of 9% to body regions (head 9%, each arm 9%, each leg 18%, trunk 36%) to estimate the TBSA burned, guiding fluid resuscitation.", tags: ["burns", "rule of nines"] }));
