file24.push(M("med", { subject: "surgery", chapter: "sur-trauma", topic: "t-337", difficulty: "medium", question: "In trauma management, ABC stands for:", optionA: "Airway, Breathing, Circulation", optionB: "Antibiotics, Bandages, Casts", optionC: "Assessment, Blood, Care", optionD: "Ankle, Bone, Chest", correctAnswer: "A", detailedExplanation: "Advanced trauma life support begins with Airway maintenance, Breathing assessment and Circulation control - the priority sequence to save life in trauma.", tags: ["trauma", "ABC"] }));
