file24.push(M("med", { subject: "community-medicine", chapter: "com-epidemiology", topic: "t-338", difficulty: "medium", question: "Incidence measures:", optionA: "All existing cases at a point in time", optionB: "New cases occurring in a population over a period", optionC: "Deaths from a disease", optionD: "Disease severity", correctAnswer: "B", detailedExplanation: "Incidence counts new cases over time and reflects disease risk; prevalence counts all existing cases at a point in time and reflects disease burden.", tags: ["incidence", "epidemiology"] }));
file24.push(M("med", { subject: "community-medicine", chapter: "com-epidemiology", topic: "t-339", difficulty: "easy", question: "A screening test's sensitivity measures:", optionA: "Correct identification of healthy people", optionB: "Correct identification of people with the disease", optionC: "Cost of the test", optionD: "Speed of the test", correctAnswer: "B", detailedExplanation: "Sensitivity is the probability that a diseased person tests positive; specificity is the probability that a healthy person tests negative. High sensitivity avoids missed cases.", tags: ["screening", "sensitivity"] }));
