file24.push(M("med", { subject: "community-medicine", chapter: "com-health", topic: "t-340", difficulty: "medium", question: "Herd immunity is achieved when:", optionA: "Every person is hospitalised", optionB: "A high proportion of the population is immune, protecting the unvaccinated", optionC: "Only children are vaccinated", optionD: "Disease disappears worldwide", correctAnswer: "B", detailedExplanation: "When a large fraction of a population is immunised, transmission chains break, indirectly protecting those who cannot be vaccinated (infants, immunocompromised) - herd immunity.", tags: ["herd immunity", "vaccination"] }));
