/* auditing */
file24.push(M("aud", { subject: "auditing", chapter: "aud-fundamentals", topic: "t-342", difficulty: "easy", question: "An audit is best defined as:", optionA: "Preparation of financial statements", optionB: "Independent examination of financial statements and records", optionC: "Tax computation", optionD: "Budget planning", correctAnswer: "B", detailedExplanation: "Auditing is the systematic, independent examination of financial statements and underlying records to express an opinion on whether they present a true and fair view.", tags: ["audit", "fundamentals"] }));
