file24.push(M("aud", { subject: "auditing", chapter: "aud-fundamentals", topic: "t-343", difficulty: "easy", question: "Audit evidence should be:", optionA: "Sufficient and appropriate", optionB: "Voluminous", optionC: "Cheap", optionD: "Oral only", correctAnswer: "A", detailedExplanation: "ISA 500 requires audit evidence to be sufficient (quantity) and appropriate (relevance and reliability) to support the auditor's opinion.", tags: ["audit evidence"] }));
file24.push(M("aud", { subject: "auditing", chapter: "aud-fundamentals", topic: "t-343", difficulty: "medium", question: "Materiality in auditing refers to:", optionA: "The audit fee", optionB: "Misstatements that could influence users' economic decisions", optionC: "The auditor's working hours", optionD: "Company assets", correctAnswer: "B", detailedExplanation: "Information is material if omitting or misstating it could reasonably influence decisions of financial statement users; materiality guides audit planning and evaluation.", tags: ["materiality"] }));
