file24.push(M("aud", { subject: "auditing", chapter: "aud-standards", topic: "t-345", difficulty: "medium", question: "An unqualified (clean) audit opinion states that the financial statements:", optionA: "Contain serious misstatements", optionB: "Present a true and fair view in all material respects", optionC: "Could not be audited", optionD: "Only partially comply", correctAnswer: "B", detailedExplanation: "An unqualified opinion concludes the financial statements are presented fairly, in all material respects, in accordance with the applicable financial reporting framework.", tags: ["audit opinion"] }));
file24.push(M("aud", { subject: "auditing", chapter: "aud-standards", topic: "t-345", difficulty: "medium", question: "Audit sampling is used when:", optionA: "Testing 100% of transactions is impractical", optionB: "The client requests it", optionC: "Assets are small", optionD: "The auditor is new", correctAnswer: "A", detailedExplanation: "Audit sampling applies audit procedures to a representative subset so conclusions about the whole population can be drawn efficiently; testing everything is usually impractical.", tags: ["audit sampling"] }));
