file24.push(M("scm", { subject: "supply-chain", chapter: "scm-logistics", topic: "t-346", difficulty: "medium", question: "EOQ in inventory management stands for:", optionA: "Economic Order Quantity", optionB: "Electronic Order Queue", optionC: "Estimated Output Quality", optionD: "External Operations Quota", correctAnswer: "A", detailedExplanation: "EOQ is the optimal order size that minimises the total of ordering and holding costs, balancing frequent small orders against large inventory storage.", tags: ["EOQ", "inventory"] }));
file24.push(M("scm", { subject: "supply-chain", chapter: "scm-logistics", topic: "t-347", difficulty: "medium", question: "Just-in-Time (JIT) inventory aims to:", optionA: "Keep maximum safety stock", optionB: "Receive materials exactly when needed, minimising inventory", optionC: "Produce in bulk annually", optionD: "Outsource all warehousing", correctAnswer: "B", detailedExplanation: "JIT, pioneered by Toyota, delivers materials and parts just as they are needed in production, slashing inventory holding costs and waste while demanding reliable suppliers.", tags: ["JIT", "inventory"] }));
file24.push(M("scm", { subject: "supply-chain", chapter: "scm-strategy", topic: "t-348", difficulty: "medium", question: "The bullwhip effect describes:", optionA: "Demand fluctuations amplifying as they move upstream", optionB: "Price reduction in retail", optionC: "Faster delivery times", optionD: "Warehouse automation", correctAnswer: "A", detailedExplanation: "Small demand swings at the retail end become increasingly distorted and amplified toward suppliers - the bullwhip effect - caused by forecasting, batching and price fluctuations.", tags: ["bullwhip effect"] }));
